        "file": "database_secure.tf",
        "lang": "hcl",
        "kind": "secure",
        "code": "variable \"db_password\" {\n  type        = string\n  description = \"Master password, injected at run time (TF_VAR_db_password)\"\n  sensitive   = true  # masked in plan/apply output\n  nullable    = false # null is refused: the password can never be silently unset\n  # No default: the secret never lives in the repository\n}\n\nresource \"aws_db_instance\" \"main\" {\n  identifier          = \"shop-db\"\n  engine              = \"postgres\"\n  instance_class      = \"db.t4g.micro\"\n  allocated_storage   = 20\n  username            = \"shop_admin\"\n  password            = var.db_password\n  storage_encrypted   = true\n  skip_final_snapshot = true\n}\n\n# Expose what consumers need, not the secret\noutput \"db_endpoint\" {\n  description = \"Host and port of the database\"\n  value       = aws_db_instance.main.endpoint\n}\n",
