        "code": "locals {\n  vpc_cidr = \"10.20.0.0/16\"\n  azs      = [\"eu-west-3a\", \"eu-west-3b\", \"eu-west-3c\"]\n\n  # List -> map: one /24 per availability zone, no address typed by hand\n  private_subnets = {\n    for index, az in local.azs : az => cidrsubnet(local.vpc_cidr, 8, index + 10)\n  }\n\n  users = {\n    alice = { role = \"admin\", mfa = true }\n    bob   = { role = \"developer\", mfa = false }\n    carol = { role = \"admin\", mfa = false }\n  }\n\n  # Map -> list with a filter: administrators without multi-factor authentication\n  admins_without_mfa = [\n    for name, user in local.users : name if user.role == \"admin\" && !user.mfa\n  ]\n\n  # Map -> map: keep only the role of each user, in upper case\n  roles = { for name, user in local.users : name => upper(user.role) }\n}\n\noutput \"private_subnets\" {\n  value = local.private_subnets\n}\n\noutput \"admins_without_mfa\" {\n  value = local.admins_without_mfa\n}\n",
