        "file": "security_group.tf",
        "lang": "hcl",
        "kind": "neutral",
        "code": "variable \"vpc_id\" {\n  type        = string\n  description = \"VPC hosting the web servers\"\n}\n\nvariable \"ingress_rules\" {\n  type = list(object({\n    description = string\n    port        = number\n    cidr_blocks = list(string)\n  }))\n  default = [\n    { description = \"HTTPS from the Internet\", port = 443, cidr_blocks = [\"0.0.0.0/0\"] },\n    { description = \"SSH from the VPN only\", port = 22, cidr_blocks = [\"10.8.0.0/24\"] },\n  ]\n}\n\nresource \"aws_security_group\" \"web\" {\n  name        = \"web\"\n  description = \"Inbound rules of the web servers\"\n  vpc_id      = var.vpc_id\n\n  # One nested \"ingress\" block is generated per element of the list\n  dynamic \"ingress\" {\n    for_each = var.ingress_rules\n\n    content {\n      # The iterator is named after the block: ingress.value\n      description = ingress.value.description\n      from_port   = ingress.value.port\n      to_port     = ingress.value.port\n      protocol    = \"tcp\"\n      cidr_blocks = ingress.value.cidr_blocks\n    }\n  }\n}\n",
