        "file": "iam.tf",
        "lang": "hcl",
        "kind": "secure",
        "code": "# Who am I? Avoids hard-coding the 12-digit account ID\ndata \"aws_caller_identity\" \"current\" {}\n\n# Trust policy: only the EC2 service may assume this role\ndata \"aws_iam_policy_document\" \"assume_ec2\" {\n  statement {\n    sid     = \"AllowEc2ToAssume\"\n    effect  = \"Allow\"\n    actions = [\"sts:AssumeRole\"]\n\n    principals {\n      type        = \"Service\"\n      identifiers = [\"ec2.amazonaws.com\"]\n    }\n  }\n}\n\nresource \"aws_iam_role\" \"app\" {\n  name               = \"shop-app\"\n  assume_role_policy = data.aws_iam_policy_document.assume_ec2.json\n}\n\n# Permissions: read the application parameters, nothing else\ndata \"aws_iam_policy_document\" \"read_config\" {\n  statement {\n    sid     = \"ReadShopParameters\"\n    effect  = \"Allow\"\n    actions = [\"ssm:GetParameter\", \"ssm:GetParametersByPath\"]\n    resources = [\n      \"arn:aws:ssm:eu-west-3:${data.aws_caller_identity.current.account_id}:parameter/shop/*\",\n    ]\n  }\n}\n\nresource \"aws_iam_role_policy\" \"read_config\" {\n  name   = \"read-config\"\n  role   = aws_iam_role.app.id\n  policy = data.aws_iam_policy_document.read_config.json\n}\n",
