        "code": "provider \"aws\" {\n  region = \"eu-west-3\"\n}\n\nlocals {\n  queues = {\n    orders   = { retention_days = 7 }\n    invoices = { retention_days = 14 }\n  }\n}\n\nmodule \"queue\" {\n  source   = \"./modules/private-queue\"\n  for_each = local.queues\n\n  # Inputs = the variables declared in the module\n  name           = each.key\n  environment    = \"prod\"\n  retention_days = each.value.retention_days\n  tags           = { Team = \"payments\" }\n}\n\n# Outputs of a for_each module are read with a key\noutput \"orders_queue_url\" {\n  value = module.queue[\"orders\"].queue_url\n}\n\noutput \"all_queue_arns\" {\n  value = { for name, queue in module.queue : name => queue.queue_arn }\n}\n",
